script:
setTimeout(function() {
    let parent = (typeof root_element !== 'undefined') ? root_element : document;
    
    let chart_div = parent.querySelector('#payment-chart');
    let legend_div = parent.querySelector('#custom-legend');
    let prev_btn = parent.querySelector('#prev-year-btn');
    let next_btn = parent.querySelector('#next-year-btn');
    let year_display = parent.querySelector('#current-year-display');
    let no_data_div = parent.querySelector('#no-data-msg');

    if (!chart_div || !legend_div || !prev_btn || !next_btn || !year_display) return;

    let current_year = new Date().getFullYear();
    year_display.innerText = current_year;

    const month_names = {
        "Jan": "January", "Feb": "February", "Mar": "March",
        "Apr": "April", "May": "May", "Jun": "June",
        "Jul": "July", "Aug": "August", "Sep": "September",
        "Oct": "October", "Nov": "November", "Dec": "December"
    };

    // خريطة تحويل الأشهر لأرقام لبناء التاريخ بصيغة YYYY-MM-DD
    const month_numbers = {
        "Jan": "01", "Feb": "02", "Mar": "03", "Apr": "04", "May": "05", "Jun": "06",
        "Jul": "07", "Aug": "08", "Sep": "09", "Oct": "10", "Nov": "11", "Dec": "12"
    };

    function normalize_month(val) {
        if (!val) return "";
        let str = String(val).toLowerCase().trim();
        if (str.startsWith("jan") || str === "1" || str === "01") return "Jan";
        if (str.startsWith("feb") || str === "2" || str === "02") return "Feb";
        if (str.startsWith("mar") || str === "3" || str === "03") return "Mar";
        if (str.startsWith("apr") || str === "4" || str === "04") return "Apr";
        if (str.startsWith("may") || str === "5" || str === "05") return "May";
        if (str.startsWith("jun") || str === "6" || str === "06") return "Jun";
        if (str.startsWith("jul") || str === "7" || str === "07") return "Jul";
        if (str.startsWith("aug") || str === "8" || str === "08") return "Aug";
        if (str.startsWith("sep") || str === "9" || str === "09") return "Sep";
        if (str.startsWith("oct") || str === "10") return "Oct";
        if (str.startsWith("nov") || str === "11") return "Nov";
        if (str.startsWith("dec") || str === "12") return "Dec";
        return "";
    }

    // دالة التوجيه الذكية التي تحسب النطاق التاريخي وتستبعد المدفوع من الفلتر
    function navigate_to_filtered_list(month_key, year) {
        let mm = month_numbers[month_key];
        if (!mm) return;

        // حساب اليوم الأول والأخير من الشهر بصيغة YYYY-MM-DD القياسية لـ Frappe
        let from_date = `${year}-${mm}-01`;
        let last_day = new Date(year, parseInt(mm), 0).getDate();
        let to_date = `${year}-${mm}-${last_day}`;

        // تطبيق الفلتر على واجهة العرض باستخدام نطاق التاريخ + استبعاد المدفوع
        frappe.route_options = {
            "payment_due_date": ["between", [from_date, to_date]],
            "paid": 0 // يعرض فقط الحقول غير المحددة كـ Paid
        };

        frappe.set_route('List', 'Agency Contract');
    }

    function load_payment_data(year) {
        chart_div.innerHTML = '';
        legend_div.innerHTML = '';
        no_data_div.style.display = 'none';

        frappe.call({
            method: "frappe.desk.query_report.run",
            args: {
                report_name: "Agency Pending Payments Chart Report",
                filters: { year: year }
            },
            callback: function(r) {
                let rows = [];
                let columns = [];

                if (r.message) {
                    if (Array.isArray(r.message)) {
                        if (r.message.length === 2 && Array.isArray(r.message[0]) && Array.isArray(r.message[1])) {
                            columns = r.message[0];
                            rows = r.message[1];
                        } else {
                            rows = r.message;
                        }
                    } else if (typeof r.message === 'object') {
                        let res = r.message.result || r.message.data;
                        columns = r.message.columns || [];
                        if (Array.isArray(res)) {
                            rows = res;
                        } else if (res && Array.isArray(res.data)) {
                            rows = res.data;
                        }
                    }
                }

                let month_idx = -1;
                let agency_idx = -1;
                let paid_idx = -1; 

                if (columns && columns.length > 0) {
                    columns.forEach((col, idx) => {
                        let name = "";
                        if (typeof col === 'object' && col !== null) {
                            name = (col.fieldname || col.label || "").toLowerCase();
                        } else if (typeof col === 'string') {
                            name = col.split(':')[0].toLowerCase();
                        }
                        if (name.includes('month') || name.includes('شهر')) {
                            month_idx = idx;
                        }
                        if (name.includes('agency') || name.includes('agency_name') || name.includes('الوكالة') || name.includes('الوكيل')) {
                            agency_idx = idx;
                        }
                        if (name === 'paid' || name === 'is_paid' || name.includes('مدفوع') || name.includes('status')) {
                            paid_idx = idx;
                        }
                    });
                }

                const months_list = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
                
                let stages = {};
                months_list.forEach(m => {
                    stages[m] = { count: 0, agencies: new Set() };
                });

                let total = 0;

                rows.forEach(function(row) {
                    let month_val = "";
                    let agency_val = "";
                    let is_paid = false; 
                    
                    if (Array.isArray(row)) {
                        if (month_idx !== -1) month_val = row[month_idx];
                        if (agency_idx !== -1) agency_val = row[agency_idx];
                        if (paid_idx !== -1) {
                            let p_val = row[paid_idx];
                            if (p_val === 1 || p_val === true || String(p_val).toLowerCase() === 'yes' || String(p_val).toLowerCase() === 'paid') {
                                is_paid = true;
                            }
                        }
                    } else if (typeof row === 'object' && row !== null) {
                        month_val = row.month || row.Month || row.month_name || "";
                        agency_val = row.agency || row.agency_name || row.Agency || "";
                        
                        let p_val = row.paid !== undefined ? row.paid : (row.is_paid !== undefined ? row.is_paid : row.status);
                        if (p_val === 1 || p_val === true || String(p_val).toLowerCase() === 'yes' || String(p_val).toLowerCase() === 'paid') {
                            is_paid = true;
                        }
                    }

                    if (is_paid) {
                        return; 
                    }

                    let norm = normalize_month(month_val);
                    if (norm && stages[norm] !== undefined) {
                        stages[norm].count += 1;
                        if (agency_val) {
                            stages[norm].agencies.add(agency_val.trim());
                        }
                        total += 1;
                    }
                });

                if (total === 0) {
                    no_data_div.style.display = 'block';
                    return;
                }

                let entries = Object.entries(stages).filter(e => e[1].count > 0);
                let labels = entries.map(function(e) { return e[0]; });
                let values = entries.map(function(e) { return e[1].count; });

                let colors = [
                    '#E8294A','#5BB8F5','#F5A800','#0BE881','#FF6B35','#E8509A','#9B59B6','#3BAB60','#7A8FA0','#00C4C2','#E8FF52','#A18276'
                ];

                new frappe.Chart(chart_div, {
                    type: 'donut',
                    data: {
                        labels: labels,
                        datasets: [{ values: values }]
                    },
                    height: 280,
                    colors: colors,
                    isNavigable: true,
                    showLegend: false
                });

                setTimeout(function() {
                    chart_div.querySelectorAll('.donut-path').forEach(function(el, i) {
                        el.style.cursor = 'pointer';
                        el.addEventListener('click', function() {
                            navigate_to_filtered_list(labels[i], year);
                        });
                    });
                }, 1000);

                labels.forEach(function(label, i) {
                    let val = values[i];
                    let payment_text = `${val} Payment${val > 1 ? 's' : ''}`;
                    let full_month_name = month_names[label] || label;

                    let agency_set = stages[label].agencies;
                    let agency_list_str = agency_set.size > 0 
                        ? Array.from(agency_set).join(", ") 
                        : "No assigned agency";

                    let item = document.createElement('div');
                    item.style.cssText = 'display:flex; align-items:flex-start; gap:8px; cursor:pointer; padding:8px; border-radius:6px; transition: background 0.2s; min-width: 0;';
                    item.innerHTML = `
                        <div style="width:10px; height:10px; border-radius:50%; background:${colors[i % colors.length]}; flex-shrink:0; margin-top: 4px;"></div>
                        <div style="width: 100%; min-width: 0;">
                            <div style="font-family:var(--font-stack); font-size:12px; font-weight:600; color:var(--heading-color); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${full_month_name}</div>
                            <div style="font-family:var(--font-stack); font-size:11px; color:var(--text-muted); margin-bottom: 2px;">${payment_text}</div>
                            <div style="font-family:var(--font-stack); font-size:10px; color:var(--text-color); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; opacity: 0.8;" title="${agency_list_str}">🏢 ${agency_list_str}</div>
                        </div>
                    `;
                    
                    item.addEventListener('mouseenter', function() { item.style.background = 'var(--fg-hover-color)'; });
                    item.addEventListener('mouseleave', function() { item.style.background = 'transparent'; });
                    
                    item.addEventListener('click', function() {
                        navigate_to_filtered_list(label, year);
                    });
                    
                    legend_div.appendChild(item);
                });
            }
        });
    }

    load_payment_data(current_year);

    prev_btn.addEventListener('click', function() {
        current_year--;
        year_display.innerText = current_year;
        load_payment_data(current_year);
    });

    next_btn.addEventListener('click', function() {
        current_year++;
        year_display.innerText = current_year;
        load_payment_data(current_year);
    });

}, 2500);
